/**
 * Resource loader tests (Level 2): a temporary directory is populated with *real* format bytes
 * generated by `mu-formats`, then read back through the loader — including the awkward cases a data
 * tree copied from Windows brings (mixed case, nested paths, replacement mid-session).
 */

import assert from 'node:assert/strict';
import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve as resolvePath } from 'node:path';
import test from 'node:test';

import {
  buildAttFixture,
  buildBmdFixture,
  buildMapFixture,
  buildObjFixture,
  buildOztFixture,
  buildTgaFixture,
  decodeOzt,
} from '@mu-reengineer/formats';

import { DEFAULT_PATHS, ResourceLoader, ResourceNotFoundError } from '../resources/loader.js';

async function withDataDir<T>(populate: (root: string) => Promise<void>, run: (loader: ResourceLoader, root: string) => Promise<T>): Promise<T> {
  const root = await mkdtemp(join(tmpdir(), 'mu-resources-'));
  try {
    await populate(root);
    return await run(new ResourceLoader({ root }), root);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}

test('loads a terrain bundle by the classic server-side naming, ignoring case', async () => {
  await withDataDir(
    async (root) => {
      await mkdir(join(root, 'World1'), { recursive: true });
      await writeFile(join(root, 'World1', 'encterrain1.ATT'), buildAttFixture({ extended: true }).bytes);
      await writeFile(join(root, 'World1', 'EncTerrain1.map'), buildMapFixture().bytes);
      await writeFile(join(root, 'World1', 'EncTerrain1.obj'), buildObjFixture().bytes);
    },
    async (loader) => {
      const { att, map, obj } = await loader.loadTerrain(1);
      assert.equal(att.attributes.length, 256 * 256);
      assert.equal(att.isExtended, true);
      assert.equal(map.layer1.length, 256 * 256);
      assert.equal(obj.objects.length, 2);
      assert.equal((await loader.resolve('world1/encterrain1.ATT')).endsWith('encterrain1.ATT'), true);
      assert.deepEqual(Object.keys(DEFAULT_PATHS), ['att', 'map', 'obj']);
    },
  );
});

test('the cache serves the second read and invalidates when the file changes', async () => {
  await withDataDir(
    async (root) => {
      await writeFile(join(root, 'model.bmd'), buildBmdFixture({ version: 12, name: 'one' }).bytes);
    },
    async (loader, root) => {
      assert.ok(root.length > 0);
      const first = await loader.loadBmd('model.bmd');
      assert.equal(first.name, 'one');
      assert.deepEqual(
        { hits: loader.stats.hits, misses: loader.stats.misses, entries: loader.stats.entries },
        { hits: 0, misses: 1, entries: 1 },
      );
      assert.ok(loader.stats.bytesRead > 0, 'the first read must come from the disk');

      const second = await loader.loadBmd('MODEL.BMD');
      assert.equal(second.name, 'one');
      assert.equal(loader.stats.hits, 1, 'the second read must come from the cache');
      assert.equal(loader.stats.misses, 1);

      // replacing the file must invalidate the cache (size changes => new bytes are served)
      const replacement = buildBmdFixture({ version: 15, name: 'two' }).bytes;
      await writeFile(join(root, 'model.bmd'), replacement);
      const third = await loader.loadBmd('model.bmd');
      assert.equal(third.name, 'two');
      assert.equal(loader.stats.misses, 2, 'a changed file must be re-read');

      loader.clear();
      assert.equal(loader.stats.entries, 0);
    },
  );
});

test('missing files report close candidates instead of a bare error', async () => {
  await withDataDir(
    async (root) => {
      await writeFile(join(root, 'World9_EncTerrain9.att'), buildAttFixture().bytes);
    },
    async (loader) => {
      await assert.rejects(
        () => loader.loadAtt('World9/EncTerrain9.att'),
        (error: unknown) => {
          assert.ok(error instanceof ResourceNotFoundError);
          assert.match(error.message, /resource not found/);
          assert.ok(error.candidates.some((candidate) => candidate.includes('EncTerrain9')), `candidates: ${error.candidates}`);
          return true;
        },
      );
    },
  );
});

test('paths cannot escape the data directory', async () => {
  await withDataDir(
    async (root) => {
      await writeFile(join(root, 'ok.att'), buildAttFixture().bytes);
    },
    async (loader) => {
      await assert.rejects(() => loader.read('../../etc/passwd'), /must stay inside the data directory/);
      await assert.rejects(() => loader.read('../ok.att'), /must stay inside/);
    },
  );
});

test('textures are decoded through the loader and the directory can be listed', async () => {
  await withDataDir(
    async (root) => {
      await mkdir(join(root, 'World1', 'tiles'), { recursive: true });
      await writeFile(join(root, 'World1', 'tiles', 'grass.OZT'), buildOztFixture(4, 3).bytes);
      await writeFile(join(root, 'World1', 'tiles', 'stone.tga'), buildTgaFixture(2, 2).bytes);
      await writeFile(join(root, 'World1', 'tiles', 'notes.txt'), new Uint8Array([1, 2, 3]));
    },
    async (loader) => {
      const image = await loader.loadTexture('world1/tiles/GRASS.ozt');
      const expected = decodeOzt(buildOztFixture(4, 3).bytes);
      assert.equal(image.width, expected.width);
      assert.equal(image.height, expected.height);
      assert.deepEqual([...image.rgba], [...expected.rgba]);

      const tga = await loader.loadTexture('World1/tiles/stone.tga');
      assert.equal(tga.width, 2);
      assert.equal(tga.height, 2);

      await assert.rejects(() => loader.loadTexture('World1/tiles/notes.txt'), /unsupported texture format/);

      const files = await loader.list();
      assert.deepEqual(files, ['World1/tiles/grass.OZT', 'World1/tiles/notes.txt', 'World1/tiles/stone.tga']);
    },
  );
});

test('a loader can be built from the environment and reports its root', async () => {
  const loader = ResourceLoader.fromEnvironment({ MU_REENGINEER_DATA: '/tmp/does-not-matter' });
  assert.ok(loader);
  assert.equal(loader.root, resolvePath('/tmp/does-not-matter'));
  assert.equal(ResourceLoader.fromEnvironment({}), undefined);
});
